package clusterdata.datatypes;

import java.io.Serializable;

public class TaskEvent implements Serializable {
    private static final long serialVersionUID = 1L;

    public long timestamp;        // microseconds
    public String missing;         // missing info indicator
    public long jobId;
    public long taskIdx;
    public long machineId;
    public int eventType;          // 0=SUBMIT, 1=SCHEDULE, 4=FINISH, etc.
    public String user;
    public int schedCls;
    public int priority;
    public double cpuRequested;
    public double memRequested;
    public double disk;
    public int restriction;

    public TaskEvent() {
    }

    public TaskEvent(long timestamp, String missing, long jobId, long taskIdx, long machineId,
                     int eventType, String user, int schedCls, int priority, double cpuRequested,
                     double memRequested, double disk, int restriction) {
        this.timestamp = timestamp;
        this.missing = missing;
        this.jobId = jobId;
        this.taskIdx = taskIdx;
        this.machineId = machineId;
        this.eventType = eventType;
        this.user = user;
        this.schedCls = schedCls;
        this.priority = priority;
        this.cpuRequested = cpuRequested;
        this.memRequested = memRequested;
        this.disk = disk;
        this.restriction = restriction;
    }

    public static TaskEvent fromCsvLine(String line) {
        String[] fields = line.split(",", -1);
        if (fields.length < 13) {
            return null;
        }

        try {
            TaskEvent event = new TaskEvent();
            event.timestamp = Long.parseLong(fields[0]);
            event.missing = fields[1];
            event.jobId = Long.parseLong(fields[2]);
            event.taskIdx = Long.parseLong(fields[3]);
            event.machineId = fields[4].isEmpty() ? -1 : Long.parseLong(fields[4]);
            event.eventType = Integer.parseInt(fields[5]);
            event.user = fields[6];
            event.schedCls = Integer.parseInt(fields[7]);
            event.priority = Integer.parseInt(fields[8]);
            event.cpuRequested = Double.parseDouble(fields[9]);
            event.memRequested = Double.parseDouble(fields[10]);
            event.disk = Double.parseDouble(fields[11]);
            event.restriction = Integer.parseInt(fields[12]);
            return event;
        } catch (Exception e) {
            return null;
        }
    }

    @Override
    public String toString() {
        return "TaskEvent{" +
                "timestamp=" + timestamp +
                ", jobId=" + jobId +
                ", taskIdx=" + taskIdx +
                ", eventType=" + eventType +
                '}';
    }
}

